package com.blu.imdg;

import org.apache.ignite.Ignite;
import org.apache.ignite.IgniteCache;
import org.apache.ignite.Ignition;
import org.apache.ignite.configuration.IgniteConfiguration;
import org.apache.ignite.spi.discovery.tcp.TcpDiscoverySpi;
import org.apache.ignite.spi.discovery.tcp.ipfinder.multicast.TcpDiscoveryMulticastIpFinder;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import java.util.Arrays;
import java.util.concurrent.TimeUnit;

/**
 * Improved Ignite example with proper error handling and logging
 */
public class HelloIgnite {
    private static final Logger LOG = LoggerFactory.getLogger(HelloIgnite.class);
    private static final int CACHE_SIZE = 100;
    private static final String CACHE_NAME = "testCache";
    private static final String[] DISCOVERY_NODES = {"localhost"};

    public static void main(String[] args) {
        try {
            LOG.info("Starting Ignite cluster");

            // Create TCP Discovery SPI
            TcpDiscoverySpi spi = new TcpDiscoverySpi();
            TcpDiscoveryMulticastIpFinder ipFinder = new TcpDiscoveryMulticastIpFinder();
            ipFinder.setAddresses(Arrays.asList(DISCOVERY_NODES));
            spi.setIpFinder(ipFinder);

            // Configure Ignite
            IgniteConfiguration cfg = new IgniteConfiguration();
            cfg.setClientMode(false);
            cfg.setDiscoverySpi(spi);
            cfg.setClientMode(false);

            // Start Ignite
            Ignite ignite = Ignition.start(cfg);

            // Get or create cache
            IgniteCache<Integer, String> cache = ignite.getOrCreateCache(CACHE_NAME);

            // Populate cache
            for (int i = 1; i <= CACHE_SIZE; i++) {
                cache.put(i, "Hello Worlds: " + i);
            }

            // Retrieve and log
            for (int i = 1; i <= CACHE_SIZE; i++) {
                String value = cache.get(i);
                if (value != null) {
                    LOG.info("Cache get: {}", value);
                }
            }

            // Graceful shutdown
            ignite.close();
            LOG.info("Ignite cluster stopped");

        } catch (Exception e) {
            LOG.error("Ignite operation failed", e);
            throw new RuntimeException("Ignite failed to start", e);
        }
    }
}
```

**Justification:**
- Added SLF4J logging instead of System.out.println (per POM slf4j dependency)
- Extracted constants to improve maintainability
- Added try-catch for exception handling
- Removed commented-out configuration lines
- Fixed typo: `discovery§` → `discoverySpi`
- Added graceful shutdown logging

